def choose_move(observation):
    px, py = observation['self_position']
    ox, oy = observation['opponent_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation['resources']
    obstacles = set(observation['obstacles'])
    def dist(a, b): return abs(a[0]-b[0]) + abs(a[1]-b[1])
    target = None
    min_d = float('inf')
    for r in resources:
        d = dist((px, py), r)
        if d < min_d:
            min_d = d
            target = r
    dx = dy = 0
    if target:
        x_diff = target[0] - px
        y_diff = target[1] - py
        if abs(x_diff) > abs(y_diff):
            dx = 1 if x_diff > 0 else -1
        elif y_diff != 0:
            dy = 1 if y_diff > 0 else -1
    else:
        if px < width -1 and (px+1, py) not in obstacles:
            dx = 1
        elif px > 0 and (px-1, py) not in obstacles:
            dx = -1
        elif py < height -1 and (px, py+1) not in obstacles:
            dy = 1
        elif py > 0 and (px, py-1) not in obstacles:
            dy = -1
    return [dx, dy]
